@ResponseBody
    @RequestMapping(value = "/downloadOssFile")//APPLICATION_OCTET_STREAM
    @ApiOperation(value = "下载信息", httpMethod = "GET", notes = "下载符合条件的Excel", produces = MediaType.APPLICATION_OCTET_STREAM)
    public void download(@RequestParam String sourceFilePath, @RequestParam String sourceFileName,
                         HttpServletResponse response) throws Exception {
        String localFilePath = baseFilePath + File.separator + "oss" + File.separator;
        FileHandleBean fileHandleBean = new FileHandleBean();
        fileHandleBean.setSourceFilePath(sourceFilePath);
        fileHandleBean.setSourceFileName(sourceFileName);
        fileHandleBean.setTargetFilePath(localFilePath);
        fileHandleBean.setTargetFileName(sourceFileName);

        FileServerDo fileServerDo = fileServerDoTunnel.selectByFileServerNo("OS00001");

        fileHandleBean.setUrl(fileServerDo.getUrl());
        fileHandleBean.setUserName(fileServerDo.getUserName());
        fileHandleBean.setPassword(fileServerDo.getPassword());
        fileHandleBean.setPort(fileServerDo.getPort());
        fileHandleService.download(fileHandleBean);


        try (InputStream inputStream = new FileInputStream(new File(localFilePath, sourceFileName));
             OutputStream outputStream = response.getOutputStream();) {
            //response.setContentType("application/x-download");
            response.addHeader("Content-Disposition", "attachment;filename=" + sourceFileName);

            IOUtils.copy(inputStream, outputStream);
            outputStream.flush();
        } finally {
            FileUtil.delFolder(localFilePath);
        }
    }
